/*
 * A165757  Number of reduced words of length n in Coxeter group on 5
 *          generators S_i with relations (S_i)^2 = (S_i S_j)^10 = I.
 * https://oeis.org/A165757
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is generated by the rational function (t^10 + 2*t^9 + 2*t^8
 *            + 2*t^7 + 2*t^6 + 2*t^5 + 2*t^4 + 2*t^3 + 2*t^2 + 2*t + 1) /
 *            (6*t^10 - 3*t^9 - 3*t^8 - 3*t^7 - 3*t^6 - 3*t^5 - 3*t^4 - 3*t^3
 *            - 3*t^2 - 3*t + 1). From this we obtain the linear recurrence
 *            a(0) = 1 a(n) = 2 + 3·∑_{k=1}^{n-1} a(n-k) fo...
 * Range:     u8 n <= 3, u16 n <= 7, u32 n <= 15, u64 n <= 31, u128 n <= 63,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    /* static cache of computed values */
    static seq_t *cache = NULL;          /* array of a[0..computed]               */
    static size_t cache_size = 0;        /* allocated size of cache               */
    static idx_t  computed_up_to = (idx_t)-1;  /* last index that has been computed */

    /* grow cache if necessary */
    if ((size_t)n + 1 > cache_size) {
        size_t new_size = (size_t)n + 1;
        seq_t *new_cache = (seq_t *)malloc(new_size * sizeof(seq_t));
        if (!new_cache) abort();        /* out of memory */
        if (cache) {
            /* copy existing values */
            if (computed_up_to != (idx_t)-1) {
                for (size_t i = 0; i <= (size_t)computed_up_to; ++i)
                    new_cache[i] = cache[i];
            }
            free(cache);
        }
        cache      = new_cache;
        cache_size = new_size;
    }

    /* compute values up to n if needed */
    for (idx_t i = computed_up_to + 1; i <= n; ++i) {
        if (i == 0) {
            cache[0] = (seq_t)1;
        } else {
            seq_t sum = 0;
            /* sum of the last 9 terms multiplied by 3 */
            for (idx_t k = 1; k <= 9 && k <= i; ++k)
                sum += (seq_t)3 * cache[i - k];

            seq_t last_term = 0;
            /* account for the term with coefficient +6 when i >= 10 */
            if (i >= 10)
                last_term = (seq_t)6 * cache[i - 10];

            seq_t p = 0;
            if (i <= 9)          /* 1 ≤ i ≤ 9 */
                p = (seq_t)2;
            else if (i == 10)    /* i = 10  */
                p = (seq_t)1;
            /* for i >= 11, p stays 0 */

            cache[i] = p + sum - last_term;
        }
    }

    computed_up_to = n;
    return cache[n];
}
